export async function fetchDisasterForecast(lat = 23.8103, lon = 90.4125) {
  try {
    // GitHub Codespaces-এর ব্যাকএন্ড পোর্টের সাথে অটোমেটিক কানেক্ট করার জন্য
    const origin = window.location.origin;
    const backendUrl = origin.includes('-3000') 
      ? origin.replace('-3000', '-8000') 
      : 'http://localhost:8000';

    const response = await fetch(`${backendUrl}/api/forecast?lat=${lat}&lon=${lon}`);
    
    if (!response.ok) {
      throw new Error('Network response was not ok');
    }
    
    return await response.json();
  } catch (error) {
    console.error('API Fetch Error:', error);
    return null;
  }
}